#  HEAVEN WITNESS SIDECAR -- Stores All 154 Layer Seals
# ============================================================================


def _get_hmac_key(master_witness):
    """Derive HMAC key for sidecar signing.

    v10.5.0: Supports a real cryptographic secret via:
      1. FATIMA_HMAC_KEY environment variable (hex-encoded, min 32 bytes)
      2. .fatima_key file in the working directory (raw bytes or hex)
      3. Fallback: SHA256(Bismillah || master_witness) -- backward compatible
         but WEAK (both inputs are public/derivable from sidecar).

    The real secret is mixed with the master_witness so that:
      - Different files produce different HMAC keys (prevents cross-file replay)
      - An attacker who obtains the secret still cannot forge a sidecar
        without also computing the correct master_witness for the file

    Returns (key_bytes, method_string) tuple.
    """
    # Priority 1: Environment variable
    env_key = os.environ.get("FATIMA_HMAC_KEY", "").strip()
    if env_key and len(env_key) >= 64:  # 32 bytes = 64 hex chars
        try:
            secret = bytes.fromhex(env_key)
            # Mix secret with master_witness for per-file uniqueness
            mixed = hashlib.sha256(secret + master_witness.encode('utf-8')).digest()
            return mixed, "HMAC-SHA256(env_secret + master_witness)"
        except ValueError:
            pass  # Not valid hex, fall through

    # Priority 2: Key file
    key_file = os.path.join(os.getcwd(), '.fatima_key')
    if os.path.isfile(key_file):
        try:
            with open(key_file, 'rb') as f:
                secret = f.read(64)  # Read up to 64 bytes
            if len(secret) >= 32:
                mixed = hashlib.sha256(secret + master_witness.encode('utf-8')).digest()
                return mixed, "HMAC-SHA256(file_secret + master_witness)"
        except Exception:
            pass  # File unreadable, fall through

    # Priority 3: Legacy derivation (backward compatible but weak)
    legacy_key = hashlib.sha256(
        (BISMILLAH + master_witness).encode('utf-8')
    ).digest()
    return legacy_key, "HMAC-SHA256(SHA256(Bismillah || master_witness), witness_json)"


def _write_heaven_witness(filepath, content_bytes, computation):
    """Write the 11-heaven, 154-layer witness to .witness.bismillah sidecar."""
    witness_path = filepath + '.witness.bismillah'

    witness_data = OrderedDict([
        (BISMILLAH, True),
        ("encoder_version", ENCODER_VERSION),
        ("architecture", "11-Heaven, 154-Layer FATIMA v10.0 -- Dual-Constant Witness with Generative Integrity"),
        ("total_heavens", computation["total_heavens"]),
        ("total_layers", computation["total_layers"]),
        ("layers_per_heaven", LAYERS_PER_HEAVEN),
        ("dimensional_constant", DIMENSIONAL_CONSTANT),
        ("muhkam_constant", MUHKAM_CONSTANT),
        ("mutashabih_constant", MUTASHABIH_CONSTANT),
        ("dual_constant_product", DUAL_CONSTANT_PRODUCT),
        ("name_cycling", "99 + 55 = 154 (T(10) = F(10) = 55)"),
        ("file", os.path.basename(filepath)),
        ("file_size", len(content_bytes)),
        ("muhkam_seal", compute_seal(content_bytes)),
        ("hurst_11", computation["hurst_11"]),
        ("master_witness", computation["master_witness"]),
        ("heavens", []),
        ("quranic_grounding", OrderedDict([
            ("al_hijr_15_9", "Indeed, it is We who sent down the Reminder, "
                             "and indeed, We will be its Guardian."),
            ("yusuf_12_4", "I have seen eleven stars and the sun and the moon; "
                           "I saw them prostrating to me."),
            ("fussilat_41_42", "Falsehood cannot approach it from before it or "
                               "from behind it; a revelation from One who is "
                               "Wise and Praiseworthy."),
            ("an_najm_53_14", "Near the Lote Tree of the Utmost Boundary."),
            ("al_mulk_67_3", "He who created seven heavens in layers."),
            ("nuh_71_15", "Do you not see how Allah created seven heavens in layers?"),
            ("al_mu'minun_23_17", "And We have created above you seven pathways, "
                                  "and We are never unmindful of creation."),
            ("al_imran_3_7", "It is He who has sent down to you the Book; in it "
                             "are verses that are muhkam -- they are the foundation "
                             "of the Book -- and others that are mutashabih."),
        ])),
    ])

    # Add per-heaven summaries with layer seals
    for h_summary in computation["heavens"]:
        h_idx = h_summary["heaven"]
        h_def = HEAVENS[h_idx]
        heaven_entry = OrderedDict([
            ("heaven", h_idx),
            ("name_ar", h_def["name_ar"]),
            ("name_en", h_def["name_en"]),
            ("scale", h_def["scale"]),
            ("guardian", h_def["guardian"]),
            ("guardian_meaning", h_def["guardian_meaning"]),
            ("layer_range", "{}-{}".format(h_def["layer_start"], h_def["layer_end"])),
            ("layer_count", h_summary["layer_count"]),
            ("heaven_seal", h_summary["heaven_seal"]),
            ("layer_seals", []),
        ])

        for layer in computation["layers"]:
            if h_def["layer_start"] <= layer["layer"] <= h_def["layer_end"]:
                heaven_entry["layer_seals"].append(OrderedDict([
                    ("layer", layer["layer"]),
                    ("name", layer["name"]),
                    ("seal", layer["seal"]),
                ]))

        witness_data["heavens"].append(heaven_entry)

    # v6.0: Add semantic witness data to sidecar
    # FIX (Action Item 1, Council v2.1): The previous code hardcoded
    # "CROSSED" inside an `if semantic.get("applicable"):` block, making
    # the else "BELOW" branch dead code. Every document unconditionally
    # received "CROSSED" — a conclusion that belongs to a formal proof,
    # not a witness seal. Root cause: two unrelated notions of "crossed"
    # (dual-document verification vs single-document sealing) were
    # conflated. Fixed by unanimous council vote to PENDING_FORMAL_DEFINITION.
    # Postmortem: the hardcoded value was never gated on an actual
    # boundary-crossing computation for single-document seals.
    semantic = computation.get("semantic", {})
    if semantic.get("applicable"):
        witness_data["semantic_witness"] = OrderedDict([
            ("shannon_boundary", "PENDING_FORMAL_DEFINITION"),
            ("dual_witness_status", "implemented_not_proven"),
            ("ontology_version", ONTOLOGY_VERSION),
            ("ontology_hash", ONTOLOGY_HASH),
            ("semantic_master_seal", semantic["semantic_master_seal"]),
            ("level_count", semantic["level_count"]),
            ("muhkam_witness", semantic["muhkam_witness"]),
            ("levels", []),
            ("metadata", semantic.get("metadata", {})),
            ("dual_witness_seal", computation.get("dual_witness_seal")),
            ("quranic_grounding", semantic.get("quranic_grounding", {})),
        ])
        for level in semantic["semantic_levels"]:
            witness_data["semantic_witness"]["levels"].append(OrderedDict([
                ("level", level["semantic_level"]),
                ("name", level["level_name"]),
                ("divine_name", level["divine_name"]),
                ("seal", level["seal"]),
            ]))

    try:
        # Serialize witness data
        witness_json = json.dumps(witness_data, indent=2, ensure_ascii=False)

        # v10.5.0: HMAC with real secret support (replaces v5.1 public-only key)
        # _get_hmac_key checks env var / key file first, falls back to legacy
        hmac_key, signing_method = _get_hmac_key(computation["master_witness"])
        witness_hmac = hmac.new(
            hmac_key, witness_json.encode('utf-8'), hashlib.sha256
        ).hexdigest()

        # Write witness + signature (nested format, Action Item 3c)
        # Sidecar format version history:
        #   1.0 = flat format (heavens module v5.3, muhkam_seal at top level)
        #   2.0 = nested format (witness key + sidecar_integrity HMAC)
        # v2.0 is the standardized format per Council decision.
        # Flat format (1.0) is deprecated — readers should accept both.
        signed_data = OrderedDict([
            ("sidecar_format_version", "2.0"),
            ("witness", json.loads(witness_json)),
            ("sidecar_integrity", OrderedDict([
                ("hmac_sha256", witness_hmac),
                ("signing_method", signing_method),
                ("encoder_version", ENCODER_VERSION),
            ])),
        ])
        with open(witness_path, 'w', encoding='utf-8') as f:
            json.dump(signed_data, f, indent=2, ensure_ascii=False)
    except Exception:
        pass


def verify_witness_sidecar(filepath):
    """v5.1+v10.5.0: Verify witness sidecar with HMAC + master witness recomputation.

    v10.5.0 upgrade: Previously only verified the HMAC (which used the stored
    master_witness as part of the key). This was circular — an attacker who
    replaced both the master_witness and the HMAC could forge a valid sidecar.
    Now ALSO recomputes the master witness from the actual file content and
    compares it to the stored value.

    Returns (valid, message) tuple.
    """
    witness_path = filepath + '.witness.bismillah'
    if not os.path.exists(witness_path):
        return False, "No witness sidecar found"

    try:
        with open(witness_path, 'r', encoding='utf-8') as f:
            signed_data = json.load(f)

        # Handle all sidecar format versions (Action Item 3c):
        #   - No sidecar_integrity key = v5.0 unsigned (deprecated)
        #   - Has "witness" key = v2.0 nested format (standard)
        #   - Has "muhkam_seal" at top level = v1.0 flat format (deprecated)
        if "sidecar_integrity" not in signed_data:
            # Check for flat format (v1.0) — top-level muhkam_seal
            if "muhkam_seal" in signed_data:
                return False, ("Flat sidecar format v1.0 (deprecated) -- "
                               "re-seal with v10.2.0+ to upgrade to nested format v2.0")
            return False, "Unsigned sidecar (v5.0 format -- re-seal to upgrade)"

        witness_data = signed_data.get("witness", signed_data)
        stored_hmac = signed_data["sidecar_integrity"]["hmac_sha256"]
        stored_master = witness_data.get("master_witness", "")

        # --- Step 1: Verify HMAC integrity of sidecar JSON ---
        witness_json = json.dumps(witness_data, indent=2, ensure_ascii=False)
        hmac_key, _ = _get_hmac_key(stored_master)
        computed_hmac = hmac.new(
            hmac_key, witness_json.encode('utf-8'), hashlib.sha256
        ).hexdigest()

        if not hmac.compare_digest(stored_hmac, computed_hmac):
            return False, "HMAC MISMATCH -- sidecar may be tampered"

        # --- Step 2 (v10.5.0): Recompute master witness from file content ---
        # This closes the circular-key vulnerability: even if an attacker
        # replaces master_witness + HMAC consistently, the recomputed witness
        # from the actual file will not match the forged one.
        try:
            with open(filepath, 'rb') as f:
                content_bytes = f.read()
            recomputed = compute_all_154_layers(content_bytes, filepath)
            recomputed_master = recomputed.get("master_witness", "")

            if not hmac.compare_digest(stored_master, recomputed_master):
                return False, ("WITNESS MISMATCH -- stored master_witness does not "
                               "match recomputed value from file content. "
                               "File may have been modified after sealing.")
        except Exception as e:
            # If recomputation fails, HMAC alone is still a partial check
            return True, "HMAC verified (witness recomputation skipped: {})".format(str(e))

        return True, "HMAC verified + master witness recomputed and matched"

    except Exception as e:
        return False, "Verification error: {}".format(str(e))


